package com.bike.server.system;
import com.bike.server.common.ApiResponse; import com.bike.server.common.PageResponse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") public class UserController { private final UserService service; public UserController(UserService service){this.service=service;} @GetMapping public ApiResponse<PageResponse<UserView>> list(@RequestParam(required=false)String keyword,@RequestParam(defaultValue="1")long page,@RequestParam(defaultValue="20")long pageSize){return ApiResponse.success("查询成功",service.list(keyword,page,pageSize));} @PostMapping public ApiResponse<UserView> create(@Valid @RequestBody UserCreateRequest request){return ApiResponse.success("创建成功",service.create(request));} @PutMapping("/{id}") public ApiResponse<UserView> update(@PathVariable long id,@Valid @RequestBody UserUpdateRequest request){return ApiResponse.success("更新成功",service.update(id,request));} @PutMapping("/{id}/roles") public ApiResponse<UserView> updateRoles(@PathVariable long id,@Valid @RequestBody UserRoleRequest request){return ApiResponse.success("角色已更新",service.updateRoles(id,request));} @PutMapping("/{id}/status") public ApiResponse<UserView> status(@PathVariable long id,@RequestParam boolean enabled){return ApiResponse.success("更新成功",service.updateStatus(id,enabled));} }
